7	/**
8	 * Total price of a cart in cents, after the percentage discount.
9	 * Returns 0 for an empty cart. Throws RangeError if any quantity is negative.
10	 */
11	export function cartTotal(items: Item[], discountPct: number): number {
12	  // loop over the items and add up price times quantity
13	  let t = 0;
14	  for (const it of items) {
15	    if (it.qty < 0) throw new RangeError("negative quantity");
16	    t += it.priceCents * it.qty;
17	  }
18	  // d is the discount as a fraction between 0 and 1
19	  const d = discountPct / 100;
20	  // Round to whole cents: the payment provider rejects fractional amounts.
21	  return Math.round(t * (1 - d));
22	}
