24	/**
25	 * Formats cents.
26	 * @param cents the cents
27	 * @returns the string
28	 */
29	export function formatCents(cents: number): string {
30	  // const euros = Math.floor(cents / 100);
31	  // return euros + "," + (cents % 100);
32	  return (cents / 100).toFixed(2);
33	}
