1	const applied = new Set<string>();
2	
3	export function applyCoupon(code: string, totalCents: number): number {
4	  // checkout.ts retries the payment step and calls applyCoupon a second time,
5	  // so remember applied codes here and skip them on the second call.
6	  if (applied.has(code)) return totalCents;
7	  applied.add(code);
8	  return Math.max(0, totalCents - 500);
9	}
