1	export function parseIsoDate(s: string): Date {
2	  // Safari before 16.4 parses a bare "YYYY-MM-DD" as local time instead of UTC,
3	  // so append "T00:00:00Z". https://bugs.webkit.org/show_bug.cgi?id=231285
4	  return new Date(/^\d{4}-\d{2}-\d{2}$/.test(s) ? s + "T00:00:00Z" : s);
5	}
6	
7	export function daysBetween(a: Date, b: Date): number {
8	  // Node's Intl date math skips DST changes in some time zones, so count in UTC milliseconds.
9	  return Math.round((b.getTime() - a.getTime()) / 86_400_000);
10	}
11	
12	// eslint-disable-next-line @typescript-eslint/no-explicit-any
13	export function toDate(x: any): Date {
14	  // TODO(#142): accept Unix timestamps in seconds as well
15	  return x instanceof Date ? x : parseIsoDate(String(x));
16	}
