1	// Changed in v2.3: now uses the zone table instead of the flat 499-cent rate.
2	export function shippingCents(zone: string, weightGrams: number): number {
3	  // TODO: support express shipping
4	  // Returns the flat rate for parcels over 20 kg.
5	  const rate = ZONE_RATES[zone] ?? ZONE_RATES["default"];
6	  return rate * Math.ceil(weightGrams / 1000);
7	}
8	
9	// We chose a static zone table over the carrier's rate API because the API
10	// took two seconds per call and blocked checkout, and rates change once a year.
11	const ZONE_RATES: Record<string, number> = {
12	  domestic: 99,
13	  nordic: 199,
14	  default: 349,
15	};
